scores = [85, 92, 71, 88, 60, 95, 58, 73, 66, 80]
passed = failed = 0
for score in scores:
    if score >= 70:
        passed += 1
    else:
        failed += 1
percentage = passed / len(scores) * 100
print(f'Сдали: {passed}  Не сдали: {failed}  Процент: {percentage}%')

nums = []
for _ in range(8):
    nums.append(int(input()))
first = nums[:4]
second = nums[4:]
print(first)
print(second)
if sum(first) > sum(second):
    print('Первая половина больше')
elif sum(first) < sum(second):
    print('Вторая половина больше')
else:
    print('Суммы равны')
